/*
 * Kvant tokens — plain CSS custom properties, no framework required.
 * Generated from the Kvant DTCG tokens (packages/tokens): change the tokens, not this file.
 * Theme = data-accent × data-mode on <html> (set before first paint).
 * Scoped theming: put BOTH data-accent and data-mode on the scoping element.
 *   data-accent  graphite | cobalt (default) | iris | aqua | jade | amber | ember | orchid
 *   data-mode    light (default) | dark
 *   data-font    inter (default) | geist
 *   data-shape   capsule (default) | density
 *   data-density regular (default) | compact
 *   data-reduce-motion   presence forces reduced motion (the OS setting applies too)
 */

:root {
  /* Typography */
  --font-sans: 'Inter Variable', 'Inter', ui-sans-serif, system-ui, -apple-system, 'Segoe UI', sans-serif;
  --font-mono: 'JetBrains Mono Variable', 'JetBrains Mono', ui-monospace, 'SF Mono', 'Menlo', monospace;

  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;

  --text-display-2xl: 72px;
  --text-display-xl: 60px;
  --text-display-lg: 48px;
  --text-display-md: 40px;
  --text-display-sm: 32px;
  --text-heading-xl: 28px;
  --text-heading-lg: 24px;
  --text-heading-md: 20px;
  --text-heading-sm: 18px;
  --text-heading-xs: 16px;
  --text-body-lg: 18px;
  --text-body-md: 16px;
  --text-body-sm: 14px;
  --text-body-xs: 13px;
  --text-label-lg: 16px;
  --text-label-md: 14px;
  --text-label-sm: 13px;
  --text-caption: 12px;
  --text-overline: 11px;

  --leading-display-2xl: 76px;
  --leading-display-xl: 64px;
  --leading-display-lg: 52px;
  --leading-display-md: 44px;
  --leading-display-sm: 36px;
  --leading-heading-xl: 36px;
  --leading-heading-lg: 32px;
  --leading-heading-md: 28px;
  --leading-heading-sm: 24px;
  --leading-heading-xs: 24px;
  --leading-body-lg: 28px;
  --leading-body-md: 24px;
  --leading-body-sm: 20px;
  --leading-body-xs: 18px;
  --leading-label-lg: 20px;
  --leading-label-md: 20px;
  --leading-label-sm: 16px;
  --leading-caption: 16px;
  --leading-overline: 16px;

  --tracking-display: 0em;
  --tracking-heading-lg: -0.002em;
  --tracking-heading-md: -0.007em;
  --tracking-heading-sm: -0.008em;
  --tracking-heading-xs: -0.009em;
  --tracking-body-lg: -0.006em;
  --tracking-body: -0.007em;
  --tracking-body-xs: -0.004em;
  --tracking-label-lg: -0.008em;
  --tracking-label-sm: -0.004em;
  --tracking-overline: 0.06em;

  /* Spacing (4px grid) and control heights */
  --spacing-1: 4px;
  --spacing-2: 8px;
  --spacing-3: 12px;
  --spacing-4: 16px;
  --spacing-5: 20px;
  --spacing-6: 24px;
  --spacing-8: 32px;
  --spacing-10: 40px;
  --spacing-12: 48px;
  --spacing-16: 64px;
  --spacing-20: 80px;
  --spacing-24: 96px;
  --spacing-0-5: 2px;
  --spacing-1-5: 6px;
  --spacing-control-xs: 24px;
  --spacing-control-sm: 32px;
  --spacing-control-md: 36px;
  --spacing-control-lg: 44px;
  --spacing-control-xl: 52px;
  --spacing-row: 48px;

  /* Radius. Controls are capsules; data-shape="density" swaps the control radii only. */
  --radius-xs: 6px;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 20px;
  --radius-2xl: 24px;
  --radius-3xl: 28px;
  --radius-4xl: 36px;
  --radius-full: 9999px;
  --radius-control-xs: var(--radius-full);
  --radius-control-sm: var(--radius-full);
  --radius-control-md: var(--radius-full);
  --radius-control-lg: var(--radius-full);
  --radius-control-xl: var(--radius-full);
  --radius-control-inner: var(--radius-full);
  --radius-badge: var(--radius-full);

  --opacity-disabled: 0.5;

  --breakpoint-sm: 640px;
  --breakpoint-md: 768px;
  --breakpoint-lg: 1024px;
  --breakpoint-xl: 1280px;
  --breakpoint-2xl: 1536px;

  --container-prose: 680px;
  --container-md: 960px;
  --container-lg: 1200px;
  --container-xl: 1440px;

  /* Motion */
  --duration-instant: 0ms;
  --duration-micro: 75ms;
  --duration-fast: 100ms;
  --duration-quick: 150ms;
  --duration-base: 200ms;
  --duration-moderate: 250ms;
  --duration-slow: 300ms;
  --duration-slower: 400ms;
  --duration-deliberate: 700ms;
  --duration-spinner: 800ms;
  --duration-shimmer: 2000ms;

  --ease-out: cubic-bezier(0.23, 1, 0.32, 1);
  --ease-standard: cubic-bezier(0.2, 0, 0, 1);
  --ease-fluid: cubic-bezier(0.32, 0.72, 0, 1);
  --ease-hover: cubic-bezier(0.25, 0.1, 0.25, 1);
  --ease-emphasized: cubic-bezier(0.05, 0.7, 0.1, 1);
  --ease-exit: cubic-bezier(0.3, 0, 0.8, 0.15);
  --ease-in-out: cubic-bezier(0.77, 0, 0.175, 1);
  /* Apple spring, bounce 0, as CSS linear(); native platforms use their own springs. */
  --ease-spring-0: linear(0, 0.005 1.1%, 0.02 2.3%, 0.045 3.6%, 0.082 5.1%, 0.16 7.7%, 0.365 13.8%, 0.462 16.9%, 0.556 20.2%, 0.637 23.4%, 0.707 26.7%, 0.766 30.1%, 0.817 33.7%, 0.861 37.5%, 0.899 42%, 0.93 46.9%, 0.954 52.4%, 0.971 58.6%, 0.991 73.8%, 1);
  /* Apple spring, bounce 0.1 (switch, segment, tabs only). */
  --ease-spring-10: linear(0, 0.006 1.3%, 0.022 2.7%, 0.05 4.2%, 0.091 5.9%, 0.178 8.9%, 0.393 15.5%, 0.493 18.7%, 0.587 22.1%, 0.668 25.4%, 0.736 28.6%, 0.794 32%, 0.844 35.4%, 0.885 39%, 0.921 43.3%, 0.95 47.9%, 0.971 53.1%, 0.986 58.9%, 1 73.4%, 1);

  /* Apple-style springs as duration + curve: use as `transition: transform var(--spring-snappy)`. */
  --spring-micro: 200ms var(--ease-spring-0);
  --spring-snappy: 300ms var(--ease-spring-10);
  --spring-smooth: 350ms var(--ease-spring-0);
  --spring-gentle: 500ms var(--ease-spring-0);

  --shift-xs: 2px;
  --shift-sm: 4px;
  --shift-md: 8px;
  --shift-lg: 16px;
  --shift-xl: 24px;

  --scale-press: 0.97;
  --scale-press-wide: 0.98;
  --scale-press-icon: 0.94;
  --scale-enter: 0.96;
  --scale-tooltip: 0.97;
  --scale-lift: 1.02;

  /* CSS animations; their @keyframes ship with tokens.css. No DTCG type: CSS only. */
  --animate-spinner: kv-spin var(--duration-spinner) linear infinite;
  --animate-shimmer: kv-shimmer var(--duration-shimmer) linear infinite;
  --animate-indeterminate: kv-indeterminate 1500ms var(--ease-in-out) infinite;

  /* Theme inputs: neutral tint and status hues (overridden per accent) */
  --tint-hue: 258;
  --tint-strength: 1;

  --hue-success: 150;
  --hue-warning: 75;
  --hue-danger: 27;
}

/* ---------- Neutrals, statuses and effects: light (also the base for dark) ---------- */

:root,
[data-mode='light'] {
  color-scheme: light;

  --ink: 0.215 calc(0.012 * var(--tint-strength)) var(--tint-hue);

  --color-background: oklch(0.982 calc(0.003 * var(--tint-strength)) var(--tint-hue));
  --color-surface-1: oklch(1 0 0);
  --color-surface-2: oklch(0.962 calc(0.005 * var(--tint-strength)) var(--tint-hue));
  --color-surface-3: oklch(0.94 calc(0.006 * var(--tint-strength)) var(--tint-hue));
  --color-overlay: oklch(1 0 0);
  --color-fg-1: oklch(var(--ink));
  --color-fg-2: oklch(0.423 calc(0.016 * var(--tint-strength)) var(--tint-hue));
  --color-fg-3: oklch(0.52 calc(0.018 * var(--tint-strength)) var(--tint-hue));
  --color-fg-4: oklch(0.535 calc(0.016 * var(--tint-strength)) var(--tint-hue));
  --color-input: oklch(0.616 calc(0.016 * var(--tint-strength)) var(--tint-hue));
  --color-border: oklch(var(--ink) / 0.14);
  --color-hairline: oklch(var(--ink) / 0.1);
  --color-separator: oklch(var(--ink) / 0.07);
  --color-fill-1: oklch(var(--ink) / 0.04);
  --color-fill-2: oklch(var(--ink) / 0.07);
  --color-fill-3: oklch(var(--ink) / 0.1);
  --color-scrim: oklch(var(--ink) / 0.32);
  --color-glass: oklch(1 0 0 / 0.8);
  --color-glass-strong: oklch(1 0 0 / 0.92);
  /* Role surfaces that differ between modes */
  --color-field: var(--color-surface-1);
  --color-control: var(--color-surface-1);
  --color-control-hover: var(--color-surface-2);
  --color-control-pressed: var(--color-surface-3);
  --color-thumb: var(--color-surface-1);
  --color-success: oklch(0.544 0.138 var(--hue-success));
  --color-success-fg: oklch(0.995 0 0);
  --color-success-soft: oklch(0.955 0.03 var(--hue-success));
  --color-success-soft-fg: oklch(0.506 0.128 var(--hue-success));
  --color-warning: oklch(0.78 0.151 var(--hue-warning));
  --color-warning-fg: oklch(0.205 0.02 var(--hue-warning));
  --color-warning-soft: oklch(0.955 0.03 var(--hue-warning));
  --color-warning-soft-fg: oklch(0.52 0.101 var(--hue-warning));
  --color-danger: oklch(0.581 0.19 var(--hue-danger));
  --color-danger-hover: oklch(0.541 0.18 var(--hue-danger));
  --color-danger-fg: oklch(0.995 0 0);
  --color-danger-soft: oklch(0.955 0.025 var(--hue-danger));
  --color-danger-soft-fg: oklch(0.537 0.19 var(--hue-danger));
  /* info follows the accent; accents that are not blue set their own h250 blue */
  --color-info: var(--color-accent);
  --color-info-fg: var(--color-accent-fg);
  --color-info-soft: var(--color-accent-soft);
  --color-info-soft-fg: var(--color-accent-soft-fg);
  --color-chart-1: oklch(0.62 0.16 255);
  --color-chart-2: oklch(0.62 0.151 50);
  --color-chart-3: oklch(0.62 0.105 178);
  --color-chart-4: oklch(0.62 0.117 88);
  --color-chart-5: oklch(0.62 0.16 345);
  --color-chart-6: oklch(0.62 0.16 140);
  --color-chart-7: oklch(0.62 0.16 295);
  --color-chart-8: oklch(0.62 0.16 25);
  /* sequential magnitude scale, one chart-1 hue light to dark; seq-1 also fills forecast bands */
  --color-seq-1: oklch(0.94 0.03 255);
  --color-seq-2: oklch(0.86 0.07 255);
  --color-seq-3: oklch(0.76 0.11 255);
  --color-seq-4: oklch(0.64 0.15 255);
  --color-seq-5: oklch(0.52 0.16 255);
  /* diverging polarity scale: neg = chart-2 hue, pos = chart-1 hue, hueless midpoint */
  --color-div-mid: oklch(0.88 0.004 255);
  --color-div-neg-2: oklch(0.62 0.151 50);
  --color-div-neg-1: oklch(0.84 0.07 50);
  --color-div-pos-1: oklch(0.84 0.07 255);
  --color-div-pos-2: oklch(0.62 0.16 255);
  /* media chrome is always dark, the same in both modes: viewer background and video letterbox */
  --color-media-bg: oklch(0.16 0.005 258);
  --color-media-glass: oklch(0.233 0.007 258 / 0.72);
  --color-media-scrim: oklch(0.16 0.005 258 / 0.7);
  --color-media-fg-1: oklch(0.965 0.004 258);
  --color-media-fg-2: oklch(0.775 0.01 258);
  --color-media-hairline: oklch(1 0 0 / 0.1);
  --color-media-fill-1: oklch(1 0 0 / 0.08);
  --color-media-fill-2: oklch(1 0 0 / 0.12);
  --color-media-ring: oklch(0.7 0.13 258);

  --shadow-raised: 0 0 0 1px var(--color-hairline), 0 1px 2px oklch(var(--ink) / 0.05);
  --shadow-control: 0 0 0 1px var(--color-border), 0 1px 2px oklch(var(--ink) / 0.06);
  --shadow-control-pressed: 0 0 0 1px var(--color-border);
  --shadow-accent-control: inset 0 1px 0 oklch(1 0 0 / 0.16), inset 0 -1px 0 oklch(0 0 0 / 0.12), 0 1px 2px oklch(var(--ink) / 0.16);
  --shadow-pressed-accent: inset 0 1px 2px oklch(0 0 0 / 0.16);
  --shadow-overlay: 0 0 0 1px var(--color-hairline), 0 2px 6px oklch(var(--ink) / 0.06), 0 12px 32px -8px oklch(var(--ink) / 0.18);
  --shadow-modal: 0 0 0 1px var(--color-hairline), 0 24px 64px -12px oklch(var(--ink) / 0.28);
  --shadow-thumb: 0 1px 2px oklch(0 0 0 / 0.2), 0 0 0 0.5px oklch(0 0 0 / 0.06);
  --shadow-segment: 0 1px 2px oklch(var(--ink) / 0.1), 0 0 0 0.5px oklch(var(--ink) / 0.12);
  --shadow-glass: 0 0 0 1px oklch(var(--ink) / 0.08), inset 0 1px 0 oklch(1 0 0 / 0.6), 0 8px 24px -8px oklch(var(--ink) / 0.16);
  --shadow-tooltip: 0 4px 12px oklch(var(--ink) / 0.16);
}

/* ---------- Neutrals, statuses and effects: dark ---------- */

[data-mode='dark'] {
  color-scheme: dark;

  --ink: 0.965 calc(0.004 * var(--tint-strength)) var(--tint-hue);

  --color-background: oklch(0.16 calc(0.005 * var(--tint-strength)) var(--tint-hue));
  --color-surface-1: oklch(0.192 calc(0.006 * var(--tint-strength)) var(--tint-hue));
  --color-surface-2: oklch(0.225 calc(0.007 * var(--tint-strength)) var(--tint-hue));
  --color-surface-3: oklch(0.258 calc(0.008 * var(--tint-strength)) var(--tint-hue));
  --color-overlay: oklch(0.232 calc(0.007 * var(--tint-strength)) var(--tint-hue));
  --color-fg-1: oklch(var(--ink));
  --color-fg-2: oklch(0.774 calc(0.01 * var(--tint-strength)) var(--tint-hue));
  --color-fg-3: oklch(0.685 calc(0.014 * var(--tint-strength)) var(--tint-hue));
  --color-fg-4: oklch(0.64 calc(0.014 * var(--tint-strength)) var(--tint-hue));
  --color-input: oklch(0.584 calc(0.014 * var(--tint-strength)) var(--tint-hue));
  --color-border: oklch(1 0 0 / 0.13);
  --color-hairline: oklch(1 0 0 / 0.09);
  --color-separator: oklch(1 0 0 / 0.07);
  --color-fill-1: oklch(1 0 0 / 0.05);
  --color-fill-2: oklch(1 0 0 / 0.08);
  --color-fill-3: oklch(1 0 0 / 0.11);
  --color-scrim: oklch(0 0 0 / 0.55);
  --color-glass: oklch(0.232 calc(0.007 * var(--tint-strength)) var(--tint-hue) / 0.82);
  --color-glass-strong: oklch(0.232 calc(0.007 * var(--tint-strength)) var(--tint-hue) / 0.92);
  --color-field: var(--color-background);
  --color-control: var(--color-surface-3);
  --color-control-hover: oklch(0.29 calc(0.009 * var(--tint-strength)) var(--tint-hue));
  --color-control-pressed: var(--color-surface-2);
  --color-thumb: oklch(0.33 calc(0.008 * var(--tint-strength)) var(--tint-hue));
  --color-success: oklch(0.511 0.13 var(--hue-success));
  --color-success-soft: oklch(0.27 0.05 var(--hue-success));
  --color-success-soft-fg: oklch(0.8 0.13 var(--hue-success));
  --color-warning: oklch(0.78 0.151 var(--hue-warning));
  --color-warning-soft: oklch(0.27 0.05 var(--hue-warning));
  --color-warning-soft-fg: oklch(0.8 0.13 var(--hue-warning));
  --color-danger: oklch(0.547 0.19 var(--hue-danger));
  --color-danger-hover: oklch(0.582 0.19 var(--hue-danger));
  --color-danger-soft: oklch(0.27 0.05 var(--hue-danger));
  --color-danger-soft-fg: oklch(0.8 0.105 var(--hue-danger));
  /* dark steps of the same scales: low values sink toward the surface, high values rise toward the ink */
  --color-seq-1: oklch(0.3 0.05 255);
  --color-seq-2: oklch(0.4 0.09 255);
  --color-seq-3: oklch(0.52 0.13 255);
  --color-seq-4: oklch(0.64 0.15 255);
  --color-seq-5: oklch(0.78 0.12 255);
  --color-div-mid: oklch(0.4 0.004 255);
  --color-div-neg-2: oklch(0.7 0.14 50);
  --color-div-neg-1: oklch(0.48 0.09 50);
  --color-div-pos-1: oklch(0.48 0.09 255);
  --color-div-pos-2: oklch(0.7 0.14 255);

  --shadow-raised: 0 0 0 1px oklch(1 0 0 / 0.07), inset 0 1px 0 oklch(1 0 0 / 0.06);
  --shadow-control: 0 0 0 1px oklch(1 0 0 / 0.08), inset 0 1px 0 oklch(1 0 0 / 0.06);
  --shadow-control-pressed: 0 0 0 1px oklch(1 0 0 / 0.08);
  --shadow-accent-control: inset 0 1px 0 oklch(1 0 0 / 0.16), inset 0 -1px 0 oklch(0 0 0 / 0.12), 0 1px 2px oklch(0 0 0 / 0.4);
  --shadow-overlay: 0 0 0 1px oklch(1 0 0 / 0.1), inset 0 1px 0 oklch(1 0 0 / 0.08), 0 12px 32px -8px oklch(0 0 0 / 0.6);
  --shadow-modal: 0 0 0 1px oklch(1 0 0 / 0.1), inset 0 1px 0 oklch(1 0 0 / 0.08), 0 24px 64px -12px oklch(0 0 0 / 0.6);
  --shadow-thumb: 0 1px 2px oklch(0 0 0 / 0.35), 0 0 0 0.5px oklch(0 0 0 / 0.2);
  --shadow-segment: 0 1px 2px oklch(0 0 0 / 0.35), inset 0 1px 0 oklch(1 0 0 / 0.08);
  --shadow-glass: 0 0 0 1px oklch(1 0 0 / 0.1), inset 0 1px 0 oklch(1 0 0 / 0.08), 0 8px 24px -8px oklch(0 0 0 / 0.5);
  --shadow-tooltip: 0 4px 12px oklch(0 0 0 / 0.4);
}

/* ---------- Accents: light values apply in both modes, dark values override them ---------- */

:root,
[data-accent='cobalt'] {
  --color-accent: oklch(0.565 0.19 258);
  --color-accent-hover: oklch(0.525 0.179 258);
  --color-accent-pressed: oklch(0.485 0.165 258);
  --color-accent-fg: oklch(0.995 0 0);
  --color-accent-soft: oklch(0.955 0.02 258);
  --color-accent-soft-hover: oklch(0.935 0.029 258);
  --color-accent-soft-fg: oklch(0.523 0.178 258);
  --color-ring: var(--color-accent);
}

:root[data-mode='dark'],
[data-accent='cobalt'][data-mode='dark'] {
  --color-accent: oklch(0.53 0.181 258);
  --color-accent-hover: oklch(0.565 0.19 258);
  --color-accent-pressed: oklch(0.51 0.174 258);
  --color-accent-soft: oklch(0.27 0.05 258);
  --color-accent-soft-hover: oklch(0.3 0.06 258);
  --color-accent-soft-fg: oklch(0.8 0.093 258);
  --color-ring: oklch(0.7 0.13 258);
}

[data-accent='graphite'] {
  --tint-hue: 286;
  --tint-strength: 0.6;

  --color-accent: oklch(0.235 0.006 286);
  --color-accent-hover: oklch(0.3 0.006 286);
  --color-accent-pressed: oklch(0.195 0.006 286);
  --color-accent-fg: oklch(0.99 0 0);
  --color-accent-soft: oklch(0.955 0.008 286);
  --color-accent-soft-hover: oklch(0.935 0.008 286);
  --color-accent-soft-fg: oklch(0.517 0.012 286);
  --color-ring: var(--color-accent);
  --color-info: oklch(0.559 0.146 250);
  --color-info-fg: oklch(0.995 0 0);
  --color-info-soft: oklch(0.955 0.03 250);
  --color-info-soft-fg: oklch(0.52 0.137 250);
  --color-success: oklch(0.544 0.15 var(--hue-success));
  --color-danger: oklch(0.581 0.15 var(--hue-danger));
  --color-danger-hover: oklch(0.541 0.142 var(--hue-danger));
}

[data-accent='graphite'][data-mode='dark'] {
  --color-accent: oklch(0.925 0.004 286);
  --color-accent-hover: oklch(0.965 0.003 286);
  --color-accent-pressed: oklch(0.875 0.004 286);
  --color-accent-fg: oklch(0.205 0.006 286);
  --color-accent-soft: oklch(0.27 0.008 286);
  --color-accent-soft-hover: oklch(0.3 0.008 286);
  --color-accent-soft-fg: oklch(0.8 0.012 286);
  --color-info: oklch(0.524 0.137 250);
  --color-info-soft: oklch(0.27 0.05 250);
  --color-info-soft-fg: oklch(0.8 0.097 250);
  --color-success: oklch(0.511 0.15 var(--hue-success));
  --color-danger: oklch(0.547 0.15 var(--hue-danger));
  --color-danger-hover: oklch(0.582 0.15 var(--hue-danger));
}

[data-accent='iris'] {
  --tint-hue: 280;

  --color-accent: oklch(0.574 0.18 283);
  --color-accent-hover: oklch(0.534 0.17 283);
  --color-accent-pressed: oklch(0.494 0.156 283);
  --color-accent-fg: oklch(0.995 0 0);
  --color-accent-soft: oklch(0.955 0.02 283);
  --color-accent-soft-hover: oklch(0.935 0.029 283);
  --color-accent-soft-fg: oklch(0.531 0.18 283);
