/* ---------- Variants: font, shape, density, reduced motion (springs become ease-out, no shifts or scales) ---------- */

[data-font='geist'] {
  --font-sans: 'Geist Variable', 'Geist', ui-sans-serif, system-ui, -apple-system, 'Segoe UI', sans-serif;
}

[data-shape='density'] {
  --radius-control-xs: 6px;
  --radius-control-sm: 8px;
  --radius-control-md: 10px;
  --radius-control-inner: 6px;
  --radius-badge: 6px;
}

[data-density='compact'] {
  --spacing-control-xs: 22px;
  --spacing-control-sm: 28px;
  --spacing-control-md: 32px;
  --spacing-control-lg: 40px;
  --spacing-control-xl: 48px;
  --spacing-row: 40px;
}

[data-reduce-motion] {
  --duration-base: 150ms;
  --duration-moderate: 150ms;
  --duration-slow: 150ms;
  --duration-slower: 150ms;
  --duration-deliberate: 150ms;
  --duration-spinner: 1600ms;

  --ease-spring-0: var(--ease-out);
  --ease-spring-10: var(--ease-out);

  --shift-xs: 0px;
  --shift-sm: 0px;
  --shift-md: 0px;
  --shift-lg: 0px;
  --shift-xl: 0px;

  --scale-press: 1;
  --scale-press-wide: 1;
  --scale-press-icon: 1;
  --scale-enter: 1;
  --scale-tooltip: 1;
  --scale-lift: 1;

  --animate-shimmer: none;
}
@media (prefers-reduced-motion: reduce) {
  :root {
    --duration-base: 150ms;
    --duration-moderate: 150ms;
    --duration-slow: 150ms;
    --duration-slower: 150ms;
    --duration-deliberate: 150ms;
    --duration-spinner: 1600ms;

    --ease-spring-0: var(--ease-out);
    --ease-spring-10: var(--ease-out);

    --shift-xs: 0px;
    --shift-sm: 0px;
    --shift-md: 0px;
    --shift-lg: 0px;
    --shift-xl: 0px;

    --scale-press: 1;
    --scale-press-wide: 1;
    --scale-press-icon: 1;
    --scale-enter: 1;
    --scale-tooltip: 1;
    --scale-lift: 1;

    --animate-shimmer: none;
  }
}

@keyframes kv-spin {
  to {
    transform: rotate(360deg);
  }
}
@keyframes kv-shimmer {
  from {
    background-position: 100% 0;
  }
  to {
    background-position: -100% 0;
  }
}
@keyframes kv-indeterminate {
  from {
    translate: -100% 0;
  }
  to {
    translate: 340% 0;
  }
}
@keyframes kv-shake {
  0%,
  100% {
    translate: 0;
  }
  16%,
  50%,
  83% {
    translate: calc(var(--shift-sm) * -1) 0;
  }
  33%,
  66% {
    translate: var(--shift-sm) 0;
  }
}

/* ---------- Base layer ---------- */
@layer base {
  html {
    background: var(--color-background);
    color: var(--color-fg-1);
    font-family: var(--font-sans);
    font-size: var(--text-body-sm);
    line-height: var(--leading-body-sm);
    letter-spacing: var(--tracking-body);
    font-kerning: normal;
    font-optical-sizing: auto;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    text-rendering: optimizeLegibility;
    -webkit-tap-highlight-color: transparent;
    caret-color: var(--color-accent);
    accent-color: var(--color-accent);
    scrollbar-color: var(--color-fill-3) transparent;
  }

  ::selection {
    background: var(--color-accent-soft-hover);
    color: var(--color-fg-1);
  }

  /* data-force-focus: docs state matrices show the ring without real focus */
  :focus-visible,
  [data-force-focus] {
    outline: 2px solid var(--color-ring);
    outline-offset: 2px;
  }

  code,
  kbd,
  samp,
  pre {
    font-family: var(--font-mono);
  }

  /* numbers in data, prices, dates and timers never jitter */
  time,
  data,
  [data-numeric] {
    font-variant-numeric: tabular-nums;
  }

  ::-webkit-scrollbar {
    width: 10px;
    height: 10px;
  }
  ::-webkit-scrollbar-thumb {
    background: var(--color-fill-3);
    border: 2px solid transparent;
    border-radius: var(--radius-full);
    background-clip: padding-box;
  }
  ::-webkit-scrollbar-track {
    background: transparent;
  }

  @media (prefers-reduced-motion: reduce) {
    *,
    ::before,
    ::after {
      scroll-behavior: auto !important;
    }
  }
}

